{"task": "List distinct service names from logs that do not follow the svc-<name>-<two digit number> naming convention", "sql": "SELECT DISTINCT service FROM logs WHERE NOT regexp_like(service, '^svc-[a-z]+-[0-9]{2}$')"}
{"task": "Count log entries per service that violate the naming convention", "sql": "SELECT service, COUNT(*) AS violation_count FROM logs WHERE NOT regexp_like(service, '^svc-[a-z0-9]+-[0-9]{2}$') GROUP BY service ORDER BY violation_count DESC"}
{"task": "Flag each log row as compliant or non-compliant with the naming convention using a CASE expression", "sql": "SELECT ts, service, CASE WHEN regexp_like(service, '^svc-[a-z]+-[0-9]{2}$') THEN 'compliant' ELSE 'non_compliant' END AS naming_status FROM logs"}
{"task": "Find error-level log messages that mention a malformed service identifier embedded in the free text message", "sql": "SELECT ts, service, message FROM logs WHERE level = 'ERROR' AND regexp_like(message, 'svc-[a-zA-Z0-9]+(?!-[0-9]{2})\\b')"}
{"task": "Identify services using uppercase letters, which violates the lowercase naming convention", "sql": "SELECT DISTINCT service FROM logs WHERE regexp_like(service, '[A-Z]')"}
{"task": "Count how many distinct valid vs invalid service names exist based on the naming convention", "sql": "SELECT CASE WHEN regexp_like(service, '^svc-[a-z]+-[0-9]{2}$') THEN 'valid' ELSE 'invalid' END AS status, COUNT(DISTINCT service) AS distinct_services FROM logs GROUP BY status"}
{"task": "Find services missing the required svc- prefix entirely", "sql": "SELECT DISTINCT service FROM logs WHERE NOT regexp_like(service, '^svc-')"}
{"task": "Detect services that have the correct prefix and suffix pattern but use an unapproved middle segment name outside payments, auth, billing, or search", "sql": "SELECT DISTINCT service FROM logs WHERE regexp_like(service, '^svc-[a-z]+-[0-9]{2}$') AND NOT regexp_like(service, '^svc-(payments|auth|billing|search)-[0-9]{2}$')"}
{"task": "Find recent non-compliant service names seen in logs over the last 7 days along with an example message", "sql": "SELECT service, MIN(message) AS example_message, COUNT(*) AS occurrences FROM logs WHERE ts >= now() - INTERVAL '7 days' AND NOT regexp_like(service, '^svc-[a-z]+-[0-9]{2}$') GROUP BY service ORDER BY occurrences DESC"}
{"task": "Join logs and events on request path to surface events whose associated service name (parsed from message) fails the naming convention check", "sql": "SELECT e.id, e.path, l.service FROM events e JOIN logs l ON regexp_like(l.message, e.path) WHERE NOT regexp_like(l.service, '^svc-[a-z]+-[0-9]{2}$')"}

